def dijkstra_optimized(graph, src):
    V = len(graph)
    dist = [float("inf") for _ in range(V)]
    dist[src] = 0
    pq = [(0, src)]

    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
