def distribute_items(n, weights):
    # Initialize a 2D table to store the minimum difference for each subproblem
    dp = [[0] * (sum(weights) // 2 + 1) for _ in range(n + 1)]

    # Fill the table in a bottom-up manner
    for i in range(1, n + 1):
        for j in range(1, sum(weights) // 2 + 1):
            # If the current item's weight is greater than the current target weight, skip it
            if weights[i - 1] > j:
